import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
/* eslint-disable */

// Imports
import SnackBar from "@/components/SnackBar.vue";
import AddDepartment from "@/components/SettingsDialogs/AddDepartment.vue";
import DeleteDepartment from "@/components/SettingsDialogs/DeleteDepartment.vue";
import EditMasterhead from "@/components/SettingsDialogs/EditMasterhead.vue";
import { list_all_departments } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  // Components
  components: {
    AddDepartment,
    SnackBar,
    DeleteDepartment,
    EditMasterhead
  },
  // Data
  data() {
    return {
      // Table properties
      tableData: [],
      tableLoading: false,
      fixed: true,
      windowHeight: 0,
      // Search and pagination
      searchQuery: "",
      currentPage: 1,
      itemsPerPage: 10,
      sortBy: [{
        key: "department_name",
        order: "asc"
      }],
      // Table headers
      headers: [{
        title: "Group Name",
        value: "department_name",
        sortable: true,
        align: "start"
      }, {
        title: "Group Head",
        value: "department_head",
        sortable: true,
        align: "start"
      }, {
        title: "Actions",
        value: "actions",
        sortable: false,
        align: "center"
      }],
      // Dialog states
      addDialog: false,
      deleteDialog: false,
      editMasterDailog: false,
      componentCheck: 0,
      // Component data
      SnackBarComponent: {},
      rowInfo: {},
      tabName: "",
      roleActions: "roleCreation"
    };
  },
  // Computed properties
  computed: {
    filteredItems() {
      if (!this.searchQuery || this.searchQuery.trim() === "") {
        return this.tableData;
      }
      const searchTerm = this.searchQuery.toLowerCase().trim();
      return this.tableData.filter(item => item.department_name && item.department_name.toLowerCase().includes(searchTerm) || item.department_head && item.department_head.toLowerCase().includes(searchTerm));
    },
    sortedAndPaginatedItems() {
      // First sort the filtered items
      const sortedItems = this.filteredItems.slice().sort((a, b) => {
        for (const sort of this.sortBy) {
          const aValue = this.getSortValue(a[sort.key], sort.key);
          const bValue = this.getSortValue(b[sort.key], sort.key);
          if (aValue < bValue) return sort.order === "asc" ? -1 : 1;
          if (aValue > bValue) return sort.order === "asc" ? 1 : -1;
        }
        return 0;
      });

      // Then paginate
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return sortedItems.slice(start, end);
    },
    totalItems() {
      return this.filteredItems.length;
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  // Watchers
  watch: {
    searchQuery() {
      this.currentPage = 1;
    },
    currentPage(newVal) {
      // When the page changes, scroll to top of the card container
      this.$nextTick(() => {
        const cardContainer = document.querySelector(".card-container");
        if (cardContainer) {
          cardContainer.scrollIntoView({
            behavior: "smooth",
            block: "start"
          });
        } else {
          // Fallback to scrolling to top of page
          window.scrollTo({
            top: 0,
            behavior: "smooth"
          });
        }
      });
    }
  },
  // Lifecycle hooks
  created() {
    this.fetch_master_departments();
    this.windowHeight = window.innerHeight - 310;
  },
  // Methods
  methods: {
    // Sorting methods
    getSortValue(value, key) {
      if (!value) return "";
      if (key === "department_name" || key === "department_head") {
        return value.toLowerCase();
      }
      return value;
    },
    handleSortChange(newSortBy) {
      this.sortBy = newSortBy;
      this.currentPage = 1; // Reset to first page when sorting changes
    },
    // Data fetching methods
    async fetch_master_departments() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_all_departments, {
          organization_id: data.organization.organization_id,
          department_status: "ACTIVE",
          limit: 500,
          next_token: null
        }));
        this.tableLoading = false;
        var response = result.data.list_all_departments;

        // Check multiple possible data structures
        let departmentsData = null;
        if (response.details && Array.isArray(response.details)) {
          departmentsData = response.details;
        } else if (response.data && Array.isArray(response.data)) {
          departmentsData = response.data;
        } else if (response.items && Array.isArray(response.items)) {
          departmentsData = response.items;
        } else if (response.departments && Array.isArray(response.departments)) {
          departmentsData = response.departments;
        } else {
          departmentsData = [];
        }
        this.tableData = departmentsData || [];
      } catch (error) {
        this.tableData = [];
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    // Dialog management methods
    add_action() {
      this.componentCheck = 1;
      this.addDialog = true;
    },
    delete_user_items(item) {
      this.rowInfo = item;
      this.componentCheck = 2;
      this.deleteDialog = true;
    },
    edit_department(item) {
      this.rowInfo = item;
      this.tabName = "Group";
      this.editMasterDailog = true;
      this.componentCheck = 3;
    },
    close_dialogs(val) {
      if (val == 0) {
        this.addDialog = false;
        this.deleteDialog = false;
      }
    },
    // Navigation methods
    goBack() {
      this.$emit('backAction');
    },
    // Notification methods
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.addDialog = false;
      this.deleteDialog = false;
      this.editMasterDailog = false;
      this.fetch_master_departments();
    }
  }
};
